PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS config(id INTEGER PRIMARY KEY CHECK(id=1),status TEXT NOT NULL DEFAULT 'registration',registrationOpen INTEGER NOT NULL DEFAULT 1,attemptsPerPlayer INTEGER NOT NULL DEFAULT 1,maxDuration INTEGER NOT NULL DEFAULT 120,maxRoster INTEGER NOT NULL DEFAULT 5,seed INTEGER NOT NULL DEFAULT 20261013,frozen INTEGER NOT NULL DEFAULT 0,frozenBoard TEXT);
INSERT OR IGNORE INTO config(id) VALUES(1);
CREATE TABLE IF NOT EXISTS teams(id TEXT PRIMARY KEY,name TEXT NOT NULL COLLATE NOCASE UNIQUE,pokemon INTEGER NOT NULL,disqualified INTEGER NOT NULL DEFAULT 0,createdAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS players(id TEXT PRIMARY KEY,teamId TEXT NOT NULL REFERENCES teams(id),name TEXT NOT NULL,codeHash TEXT NOT NULL UNIQUE,allowance INTEGER NOT NULL CHECK(allowance>=0),used INTEGER NOT NULL DEFAULT 0 CHECK(used>=0),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,playerId TEXT NOT NULL REFERENCES players(id),teamId TEXT NOT NULL REFERENCES teams(id),pokemon INTEGER NOT NULL,seed INTEGER NOT NULL,maxDuration INTEGER NOT NULL,startedAt INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active');
CREATE UNIQUE INDEX IF NOT EXISTS one_active_session ON sessions(playerId) WHERE status='active';
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,sessionId TEXT NOT NULL UNIQUE REFERENCES sessions(id),teamId TEXT NOT NULL REFERENCES teams(id),playerId TEXT NOT NULL REFERENCES players(id),score INTEGER NOT NULL,distance INTEGER NOT NULL,coins INTEGER NOT NULL,enemies INTEGER NOT NULL,durationMs INTEGER NOT NULL,createdAt INTEGER NOT NULL,valid INTEGER NOT NULL DEFAULT 1,flagged INTEGER NOT NULL DEFAULT 0,reason TEXT,body TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS runs_team_score ON runs(teamId,valid,score DESC,createdAt);
CREATE TABLE IF NOT EXISTS admins(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,passwordHash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth(tokenHash TEXT PRIMARY KEY,role TEXT NOT NULL,subject TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,detail TEXT NOT NULL,createdAt INTEGER NOT NULL);
